/bin/bash -lc "python - <<'PY'
import os,json,urllib.request,urllib.parse
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
tool_id='toolshed.g2.bx.psu.edu/repos/iuc/extract_genomic_dna/Extract genomic DNA 1/3.0.3+galaxy3'
data=json.load(urllib.request.urlopen(urllib.request.Request(url+'/api/tools/'+urllib.parse.quote(tool_id, safe='')+'?'+urllib.parse.urlencode({'key':key,'io_details':'true'}))))
opts=[]
for inp in data['inputs']:
    if inp.get('name')=='reference_genome_cond':
        for case in inp['cases']:
            if case['value']=='cached':
                opts=case['inputs'][0]['options']
terms=['GRCh38','GCF_000001405','GCA_000001405','hg38','Homo_sapiens']
for term in terms:
    matches=[o for o in opts if term.lower() in (o[0]+' '+o[1]).lower()]
    print('TERM',term,'count',len(matches))
    for m in matches[:50]: print(m)
PY"
